// ---------------------------------------------------------------- shared

fn today() -> NaiveDate {
    Utc::now().date_naive()
}

fn ts(t: Option<Timestamp>) -> Timestamp {
    t.unwrap_or_else(crate::db::now)
}

/// The contact of the path: in the vault and not deleted (404 otherwise).
async fn path_contact(state: &AppState, vault_id: Uuid, contact_id: Uuid) -> ApiResult<contacts::Model> {
    contact_in_vault(&state.db, vault_id, contact_id).await
}

/// Each of `fields` is in the body (`Some`): a key the draft requires even
/// when its value may be null.
fn present(v: &mut Validator, fields: &[(&str, bool)]) -> bool {
    let mut all = true;
    for (field, is_present) in fields {
        if !is_present {
            v.fail(field, "required", &[]);
            all = false;
        }
    }
    all
}

/// A string field of a PATCH body: absent keeps `current`; a blank or null
/// value fails `required`.
fn patched_text(v: &mut Validator, field: &str, value: Option<String>, current: &str, max: usize) -> String {
    match value {
        None => current.to_owned(),
        Some(raw) => {
            let value = clean(Some(raw));
            if v.required(field, &value) {
                v.max_len(field, value.as_deref(), max);
            }
            value.unwrap_or_default()
        }
    }
}

/// PHP's `setDate`: a day past the end of the month rolls over.
fn set_date(year: i32, month: u32, day: u32) -> Option<NaiveDate> {
    NaiveDate::from_ymd_opt(year, month, 1)?.checked_add_signed(Duration::days(i64::from(day) - 1))
}

/// A year as a date input or an age gives it.
const MAX_YEAR: i64 = 9999;

/// The date parts of an important date: a full date that exists, a day and
/// a month, or a year alone.
fn check_date_parts(v: &mut Validator, day: Option<i64>, month: Option<i64>, year: Option<i64>) {
    v.between("day", day, 1, 31);
    v.between("month", month, 1, 12);
    v.between("year", year, 1, MAX_YEAR);
    if v.has("day") || v.has("month") || v.has("year") {
        return;
    }
    match (day, month, year) {
        (Some(d), Some(m), Some(y)) => {
            if NaiveDate::from_ymd_opt(y as i32, m as u32, d as u32).is_none() {
                v.fail("day", "date", &[]);
            }
        }
        (Some(_), Some(_), None) | (None, None, Some(_)) => {}
        (Some(_), None, _) => v.fail("month", "required_with", &[("values", "day")]),
        (None, Some(_), _) => v.fail("day", "required_with", &[("values", "month")]),
        (None, None, None) => v.fail("year", "required_without_all", &[("values", "day / month")]),
    }
}

