/// `ContactImportantDatesViewHelper::dto` of `rows`, raw.
async fn important_dates<C: ConnectionTrait>(
    db: &C,
    rows: Vec<contact_important_dates::Model>,
) -> ApiResult<Vec<ContactImportantDate>> {
    let ids: Vec<Id> = rows.iter().filter_map(|d| d.contact_important_date_type_id).collect();
    let mut types = HashMap::new();
    if !ids.is_empty() {
        for t in contact_important_date_types::Entity::find()
            .filter(contact_important_date_types::Column::Id.is_in(ids))
            .all(db)
            .await?
        {
            types.insert(t.id, t);
        }
    }
    let today = today();
    Ok(rows
        .into_iter()
        .map(|d| ContactImportantDate {
            day: d.day.map(i64::from),
            month: d.month.map(i64::from),
            year: d.year.map(i64::from),
            age: super::views::age(d.day, d.month, d.year, today),
            contact_important_date_type: d
                .contact_important_date_type_id
                .and_then(|id| types.get(&id).cloned())
                .map(date_type),
            id: d.id,
            contact_id: d.contact_id,
            label: d.label,
            created_at: ts(d.created_at),
            updated_at: ts(d.updated_at),
        })
        .collect())
}

