// ---------------------------------------------------------------- reminders

const REMINDER_TYPES: [&str; 4] = [TYPE_ONE_TIME, TYPE_RECURRING_DAY, TYPE_RECURRING_MONTH, TYPE_RECURRING_YEAR];

/// The date `ScheduleContactReminderForUser` schedules the reminder on:
/// its date (year 1900 when it has none) if it is after `today`, else its
/// day and month this year if that is after `today`, else next year.
fn next_occurrence(day: Option<i32>, month: Option<i32>, year: Option<i32>, today: NaiveDate) -> Option<NaiveDate> {
    let (Some(month @ 0..=12), Some(day @ 0..=31)) = (month, day) else { return None };
    let year = year.filter(|y| *y != 0).unwrap_or(1900);
    // `Carbon::parse`: month 0 and day 0 roll back like PHP's `setDate`.
    let first = NaiveDate::from_ymd_opt(year + (month - 1).div_euclid(12), ((month - 1).rem_euclid(12) + 1) as u32, 1)?;
    let mut date = first.checked_add_signed(Duration::days(i64::from(day) - 1))?;
    if date <= today {
        date = set_date(today.year(), date.month(), date.day())?;
        if date <= today {
            date = set_date(today.year() + 1, date.month(), date.day())?;
        }
    }
    Some(date)
}

fn reminder_view(r: contact_reminders::Model, today: NaiveDate) -> ContactReminder {
    ContactReminder {
        next_occurrence: next_occurrence(r.day, r.month, r.year, today),
        day: r.day.map(i64::from),
        month: r.month.map(i64::from),
        year: r.year.map(i64::from),
        id: r.id,
        contact_id: r.contact_id,
        label: r.label,
        r#type: r.r#type,
        frequency_number: r.frequency_number.map(i64::from),
        last_triggered_at: r.last_triggered_at,
        number_times_triggered: i64::from(r.number_times_triggered),
        created_at: ts(r.created_at),
        updated_at: ts(r.updated_at),
    }
}

/// `$contact->reminders()->orderBy('month')->orderBy('day')`.
