/// `$contact->addresses()` (optionally `wherePivot('is_past_address', …)`), by id.
async fn contact_addresses<C: ConnectionTrait>(
    db: &C,
    contact_id: Uuid,
    is_past_address: Option<bool>,
) -> ApiResult<Vec<ContactAddress>> {
    let mut links = contact_address::Entity::find().filter(contact_address::Column::ContactId.eq(contact_id));
    if let Some(p) = is_past_address {
        links = links.filter(contact_address::Column::IsPastAddress.eq(p));
    }
    let past: HashMap<Id, bool> = links.all(db).await?.into_iter().map(|l| (l.address_id, l.is_past_address)).collect();
    if past.is_empty() {
        return Ok(Vec::new());
    }
    let rows = addresses::Entity::find()
        .filter(addresses::Column::Id.is_in(past.keys().copied().collect::<Vec<_>>()))
        .order_by_asc(addresses::Column::Id)
        .all(db)
        .await?;
    let types = address_types_of(db, &rows).await?;
    Ok(rows
        .into_iter()
        .map(|a| {
            let p = past.get(&a.id).copied().unwrap_or(false);
            contact_address_view(a, p, &types)
        })
        .collect())
}

