/// The text fields of an address: trimmed, at most 255 characters.
fn address_text(v: &mut Validator, field: &str, value: Option<String>) -> Option<String> {
    let value = clean(value);
    v.max_len(field, value.as_deref(), 255);
    value
}

fn check_coordinates(v: &mut Validator, latitude: Option<f64>, longitude: Option<f64>) {
    if latitude.is_some_and(|l| !(-90.0..=90.0).contains(&l)) {
        v.fail("latitude", "between.numeric", &[("min", "-90"), ("max", "90")]);
    }
    if longitude.is_some_and(|l| !(-180.0..=180.0).contains(&l)) {
        v.fail("longitude", "between.numeric", &[("min", "-180"), ("max", "180")]);
    }
}

