#[utoipa::path(
    post,
    path = "/vaults/{vault_id}/contacts/{contact_id}/important-dates",
    operation_id = "createContactImportantDate",
    tag = "Contact modules",
    summary = "Add an important date to a contact",
    params(("vault_id" = uuid::Uuid, Path), ("contact_id" = uuid::Uuid, Path)),
    request_body = ContactImportantDateCreate,
    responses((status = 201, description = "The created date.", body = ContactImportantDate), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`)."), (status = 422, description = "`validation_failed` (with `errors`), `storage_limit_exceeded` or `vault_user_limit_reached`.")),
    extensions(("x-permission" = json!("vault:edit")), ("x-inventory" = json!(["R062"])), ("x-services" = json!(["CreateContactImportantDate"])))
)]
pub async fn create_contact_important_date(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((vault_id, contact_id)): Path<(Uuid, Uuid)>,
    Json(body): Json<ContactImportantDateCreate>,
) -> ApiResult<(StatusCode, Json<ContactImportantDate>)> {
    access::vault(&state, &id, vault_id, VaultPermission::Edit).await?;
    let contact = path_contact(&state, vault_id, contact_id).await?;
    let label = clean(body.label);
    let mut v = Validator::new();
    if v.required("label", &label) {
        v.max_len("label", label.as_deref(), 255);
    }
    let type_id = date_type_id(&state, &mut v, vault_id, body.contact_important_date_type_id).await?;
    let (day, month, year) = (body.day.flatten(), body.month.flatten(), body.year.flatten());
    if present(&mut v, &[("day", body.day.is_some()), ("month", body.month.is_some()), ("year", body.year.is_some())]) {
        check_date_parts(&mut v, day, month, year);
    }
    v.finish()?;
    let tx = state.db.begin().await?;
    let date = CreateContactImportantDate {
        account_id: id.user.account_id,
        vault_id,
        author_id: id.user.id,
        contact_id: contact.id,
        contact_important_date_type_id: type_id,
        label: label.unwrap_or_default(),
        day: day.map(|d| d as i32),
        month: month.map(|m| m as i32),
        year: year.map(|y| y as i32),
    }
    .execute(&tx)
    .await?;
    tx.commit().await?;
    Ok((StatusCode::CREATED, Json(one_important_date(&state.db, date).await?)))
}

#[utoipa::path(
    patch,
    path = "/vaults/{vault_id}/contacts/{contact_id}/important-dates/{important_date_id}",
    operation_id = "updateContactImportantDate",
    tag = "Contact modules",
    summary = "Edit an important date",
    params(("vault_id" = uuid::Uuid, Path), ("contact_id" = uuid::Uuid, Path), ("important_date_id" = i64, Path)),
    request_body = ContactImportantDateUpdate,
    responses((status = 200, description = "The updated date.", body = ContactImportantDate), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`)."), (status = 422, description = "`validation_failed` (with `errors`), `storage_limit_exceeded` or `vault_user_limit_reached`.")),
    extensions(("x-permission" = json!("vault:edit")), ("x-inventory" = json!(["R063"])), ("x-services" = json!(["UpdateContactImportantDate"])))
)]
pub async fn update_contact_important_date(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((vault_id, contact_id, important_date_id)): Path<(Uuid, Uuid, Id)>,
    Json(body): Json<ContactImportantDateUpdate>,
) -> ApiResult<Json<ContactImportantDate>> {
    access::vault(&state, &id, vault_id, VaultPermission::Edit).await?;
    let contact = path_contact(&state, vault_id, contact_id).await?;
    let current = contact_important_dates::Entity::live()
        .filter(contact_important_dates::Column::Id.eq(important_date_id))
        .filter(contact_important_dates::Column::ContactId.eq(contact.id))
        .one(&state.db)
        .await?
        .ok_or_else(ApiError::not_found)?;
    let mut v = Validator::new();
    let label = patched_text(&mut v, "label", body.label, &current.label, 255);
    let type_id = match body.contact_important_date_type_id {
        Some(t) => date_type_id(&state, &mut v, vault_id, t).await?,
        None => current.contact_important_date_type_id,
    };
    let parts = [("day", body.day), ("month", body.month), ("year", body.year)];
    let (day, month, year) = if parts.iter().any(|(_, p)| p.is_some()) {
        let given = parts.iter().filter(|(_, p)| p.is_some()).map(|(f, _)| *f).collect::<Vec<_>>().join(" / ");
        for (field, part) in &parts {
            if part.is_none() {
                v.fail(field, "required_with", &[("values", &given)]);
            }
        }
        let (d, m, y) = (body.day.flatten(), body.month.flatten(), body.year.flatten());
        if parts.iter().all(|(_, p)| p.is_some()) {
            check_date_parts(&mut v, d, m, y);
        }
        (d, m, y)
    } else {
        (current.day.map(i64::from), current.month.map(i64::from), current.year.map(i64::from))
    };
    v.finish()?;
    let tx = state.db.begin().await?;
    let date = UpdateContactImportantDate {
        account_id: id.user.account_id,
        vault_id,
        author_id: id.user.id,
        contact_id: contact.id,
        contact_important_date_id: current.id,
        contact_important_date_type_id: type_id,
        label,
        day: day.map(|d| d as i32),
        month: month.map(|m| m as i32),
        year: year.map(|y| y as i32),
    }
    .execute(&tx)
    .await?;
    tx.commit().await?;
    Ok(Json(one_important_date(&state.db, date).await?))
}

