#[utoipa::path(
    post,
    path = "/vaults/{vault_id}/contacts/{contact_id}/reminders",
    operation_id = "createContactReminder",
    tag = "Contact modules",
    summary = "Add a reminder to a contact",
    params(("vault_id" = uuid::Uuid, Path), ("contact_id" = uuid::Uuid, Path)),
    request_body = ContactReminderCreate,
    responses((status = 201, description = "The created reminder.", body = ContactReminder), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`)."), (status = 422, description = "`validation_failed` (with `errors`), `storage_limit_exceeded` or `vault_user_limit_reached`.")),
    extensions(("x-permission" = json!("vault:edit")), ("x-inventory" = json!(["R077"])), ("x-services" = json!(["CreateContactReminder", "ScheduleContactReminderForUser"])))
)]
pub async fn create_contact_reminder(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((vault_id, contact_id)): Path<(Uuid, Uuid)>,
    Json(body): Json<ContactReminderCreate>,
) -> ApiResult<(StatusCode, Json<ContactReminder>)> {
    access::vault(&state, &id, vault_id, VaultPermission::Edit).await?;
    let contact = path_contact(&state, vault_id, contact_id).await?;
    let label = clean(body.label);
    let year = body.year.flatten();
    let mut v = Validator::new();
    if v.required("label", &label) {
        v.max_len("label", label.as_deref(), 255);
    }
    v.required("day", &body.day);
    v.required("month", &body.month);
    present(&mut v, &[("year", body.year.is_some())]);
    check_reminder_date(&mut v, body.day, body.month, year);
    if v.required("type", &body.r#type) {
        v.one_of("type", body.r#type.as_deref(), &REMINDER_TYPES);
    }
    v.between("frequency_number", body.frequency_number, 1, i64::from(i32::MAX));
    v.finish()?;
    let tx = state.db.begin().await?;
    let reminder = CreateContactReminder {
        account_id: id.user.account_id,
        vault_id,
        author_id: id.user.id,
        contact_id: contact.id,
        label: label.unwrap_or_default(),
        day: body.day.map(|d| d as i32),
        month: body.month.map(|m| m as i32),
        year: year.map(|y| y as i32),
        r#type: body.r#type.unwrap_or_default(),
        frequency_number: body.frequency_number.map(|f| f as i32),
    }
    .execute(&tx)
    .await?;
    tx.commit().await?;
    Ok((StatusCode::CREATED, Json(reminder_view(reminder, today()))))
}

#[utoipa::path(
    patch,
    path = "/vaults/{vault_id}/contacts/{contact_id}/reminders/{reminder_id}",
    operation_id = "updateContactReminder",
    tag = "Contact modules",
    summary = "Edit a reminder",
    params(("vault_id" = uuid::Uuid, Path), ("contact_id" = uuid::Uuid, Path), ("reminder_id" = i64, Path)),
    request_body = ContactReminderUpdate,
    responses((status = 200, description = "The updated reminder.", body = ContactReminder), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`)."), (status = 422, description = "`validation_failed` (with `errors`), `storage_limit_exceeded` or `vault_user_limit_reached`.")),
    extensions(("x-permission" = json!("vault:edit")), ("x-inventory" = json!(["R078"])), ("x-services" = json!(["UpdateContactReminder", "ScheduleContactReminderForUser"])))
)]
pub async fn update_contact_reminder(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((vault_id, contact_id, reminder_id)): Path<(Uuid, Uuid, Id)>,
    Json(body): Json<ContactReminderUpdate>,
) -> ApiResult<Json<ContactReminder>> {
    access::vault(&state, &id, vault_id, VaultPermission::Edit).await?;
    let contact = path_contact(&state, vault_id, contact_id).await?;
    let current = contact_reminders::Entity::find_by_id(reminder_id)
        .filter(contact_reminders::Column::ContactId.eq(contact.id))
        .one(&state.db)
        .await?
        .ok_or_else(ApiError::not_found)?;
    let mut v = Validator::new();
    let label = patched_text(&mut v, "label", body.label, &current.label, 255);
    let day = body.day.or(current.day.map(i64::from));
    let month = body.month.or(current.month.map(i64::from));
    let year = body.year.unwrap_or(current.year.map(i64::from));
    check_reminder_date(&mut v, day, month, year);
    let r#type = match body.r#type {
        Some(t) => {
            v.one_of("type", Some(&t), &REMINDER_TYPES);
            t
        }
        None => current.r#type.clone(),
    };
    let frequency_number = match body.frequency_number {
        Some(f) => {
            v.between("frequency_number", f, 1, i64::from(i32::MAX));
            f
        }
        None => current.frequency_number.map(i64::from),
    };
    v.finish()?;
    let tx = state.db.begin().await?;
    let reminder = UpdateContactReminder {
        account_id: id.user.account_id,
        vault_id,
        author_id: id.user.id,
        contact_id: contact.id,
        contact_reminder_id: current.id,
        label,
        day: day.map(|d| d as i32),
        month: month.map(|m| m as i32),
        year: year.map(|y| y as i32),
        r#type,
        frequency_number: frequency_number.map(|f| f as i32),
    }
    .execute(&tx)
    .await?;
    tx.commit().await?;
    Ok(Json(reminder_view(reminder, today())))
}

