#[utoipa::path(
    put,
    path = "/vaults/{vault_id}/contacts/{contact_id}/job-information",
    operation_id = "setContactJobInformation",
    tag = "Contact modules",
    summary = "Set a contact's company and job position",
    params(("vault_id" = uuid::Uuid, Path), ("contact_id" = uuid::Uuid, Path)),
    request_body = JobInformationUpdate,
    responses((status = 200, description = "The contact's job information.", body = JobInformation), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`)."), (status = 422, description = "`validation_failed` (with `errors`), `storage_limit_exceeded` or `vault_user_limit_reached`.")),
    extensions(("x-permission" = json!("vault:edit")), ("x-inventory" = json!(["R092"])), ("x-services" = json!(["UpdateJobInformation"])))
)]
pub async fn set_contact_job_information(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((vault_id, contact_id)): Path<(Uuid, Uuid)>,
    Json(body): Json<JobInformationUpdate>,
) -> ApiResult<Json<JobInformation>> {
    access::vault(&state, &id, vault_id, VaultPermission::Edit).await?;
    let contact = path_contact(&state, vault_id, contact_id).await?;
    let mut v = Validator::new();
    present(&mut v, &[("company_id", body.company_id.is_some()), ("job_position", body.job_position.is_some())]);
    let company_id = body.company_id.flatten().map(Id);
    if let Some(company_id) = company_id {
        let in_vault = companies::Entity::find_by_id(company_id)
            .filter(companies::Column::VaultId.eq(vault_id))
            .one(&state.db)
            .await?
            .is_some();
        if !in_vault {
            v.fail("company_id", "exists", &[]);
        }
    }
    let job_position = clean(body.job_position.flatten());
    v.max_len("job_position", job_position.as_deref(), 255);
    v.finish()?;
    let tx = state.db.begin().await?;
    let contact = UpdateJobInformation {
        account_id: id.user.account_id,
        vault_id,
        author_id: id.user.id,
        contact_id: contact.id,
        company_id,
        job_position,
    }
    .execute(&tx)
    .await?;
    tx.commit().await?;
    Ok(Json(job_information(&state.db, &contact).await?))
}

